import { useState } from 'react';
import { JxButton, JxCalendar } from '@jinx-ui/react';

function startOfDay(d: Date): Date {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate());
}

function isSameDay(a: Date | null, b: Date): boolean {
  return (
    !!a &&
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

interface ReportDatePickerProps {
  onChange?: (date: Date | null) => void;
}

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [value, setValue] = useState<Date | null>(startOfDay(new Date()));

  const today = startOfDay(new Date());
  const yesterday = new Date(today);
  yesterday.setDate(yesterday.getDate() - 1);
  const weekAgo = new Date(today);
  weekAgo.setDate(weekAgo.getDate() - 7);

  const quickOptions: { label: string; date: Date }[] = [
    { label: 'Сегодня', date: today },
    { label: 'Вчера', date: yesterday },
    { label: 'Неделя назад', date: weekAgo },
  ];

  const handleSelect = (date: Date | null) => {
    setValue(date);
    onChange?.(date);
  };

  return (
    <div
      style={{ display: 'flex', flexDirection: 'column', gap: 12 }}
      role="group"
      aria-label="Выбор даты отчёта"
    >
      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
        {quickOptions.map((opt) => (
          <JxButton
            key={opt.label}
            type="button"
            size="sm"
            variant={isSameDay(value, opt.date) ? 'primary' : 'outline'}
            onClick={() => handleSelect(opt.date)}
          >
            {opt.label}
          </JxButton>
        ))}
      </div>
      <JxCalendar locale="ru-RU" value={value} onValueChange={handleSelect} />
    </div>
  );
}

